import{_ as a,a as t,c as o,ac as l}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 39 Am I all right?","description":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 39 Am I all right?","description":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 38 Everything except the weather","link":"/life/english/new-concept/book-2/unit-02/lesson-038"},"next":{"text":"第二册：实践与进步 · Lesson 40 Food and talk","link":"/life/english/new-concept/book-2/unit-02/lesson-040"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 38 Everything except the weather","link":"/life/english/new-concept/book-2/unit-02/lesson-038"},"next":{"text":"第二册：实践与进步 · Lesson 40 Food and talk","link":"/life/english/new-concept/book-2/unit-02/lesson-040"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-039.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-039.md"}'),n={name:"life/english/new-concept/book-2/unit-02/lesson-039.md"};function i(r,e,h,s,d,c){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="第二册-实践与进步-·-lesson-39-am-i-all-right" tabindex="-1">第二册：实践与进步 · Lesson 39 Am I all right? <a class="header-anchor" href="#第二册-实践与进步-·-lesson-39-am-i-all-right" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 39 Am I all right?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>患者向医护询问恢复情况，问题需要被准确转述；练习 whether 引导的间接疑问。本课的语言观察是：是否问句转述用 if/whether，后接陈述语序。asked whether he could leave 表在当时询问许可，不能从这句推断已经获准出院。完成学习后，请转述一次预约或许可询问，包含问题、回应和等待的行动。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>hospital</td><td>/ˈhɒspɪtəl/</td><td>n.</td><td>医院</td><td>leave hospital</td></tr><tr><td>doctor</td><td>/ˈdɒktə/</td><td>n.</td><td>医生</td><td>see a doctor</td></tr><tr><td>health</td><td>/helθ/</td><td>n.</td><td>健康</td><td>good health</td></tr><tr><td>operation</td><td>/ˌɒpəˈreɪʃən/</td><td>n.</td><td>手术；操作</td><td>a successful operation</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>ask about — 询问有关……的情况</li><li>be ready to — 准备好做某事，后接原形</li></ul><h2 id="语法讲解-间接引语与视角转换" tabindex="-1">语法讲解：间接引语与视角转换 <a class="header-anchor" href="#语法讲解-间接引语与视角转换" aria-label="Permalink to &quot;语法讲解：间接引语与视角转换&quot;">​</a></h2><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：是否问句转述用 if/whether，后接陈述语序。asked whether he could leave 表在当时询问许可，不能从这句推断已经获准出院。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Evan asked the nurse whether he could leave that afternoon.</p></blockquote><p>埃文问护士，他当天下午能否离开。</p><p>whether 引出是否问题，he could leave 为陈述语序；that afternoon 从转述者的视角定位时间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>asked whether could he leave 保留了直接问句倒装，应改为 whether he could leave。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>把 whether he could leave 连成一组，could 弱读但不遗漏；不按直接问句倒装。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Evan asked the nurse whether he could leave that afternoon. The nurse said the doctor would check him first. Evan waited in his room.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>转述一次预约或许可询问，包含问题、回应和等待的行动。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：whether 引出是否问题，he could leave 为陈述语序；that afternoon 从转述者的视角定位时间。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：asked whether could he leave 保留了直接问句倒装，应改为 whether he could leave。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选 if/that：He asked ___ he could leave.（是否）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> if</p><p><strong>解析：</strong> 转述是否疑问可用 if 或 whether。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>出院决定前谁会检查埃文？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The doctor.</p><p><strong>解析：</strong> 护士转述医生将先检查，未直接批准出院。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>转述 Can I go home?，以 He asked 开头。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He asked whether he could go home.</p><p><strong>解析：</strong> 人称 I 变 he，can 在过去视角下变 could。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：间接引语与视角转换。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-038">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-040">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=a(n,[["render",i]]);export{p as __pageData,k as default};
